<template><section class="role-form-page"><header class="role-form-page__toolbar"><div><el-button :icon="ArrowLeft" circle plain @click="back"/><div><h1>{{ isEdit?'编辑角色':'新增角色' }}</h1></div></div><div><el-button @click="back">取消</el-button><el-button type="primary" :icon="Check" :loading="submitting" @click="submit">保存</el-button></div></header><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><RoleBasicForm v-model="form"/><PermissionMatrix v-model="form.permissions" :groups="permissionCatalog"/><footer class="role-form-page__footer"><span>当前已选择 <b>{{ form.permissions.length }}</b> 项权限</span><el-button type="primary" :icon="Check" :loading="submitting" @click="submit">保存角色</el-button></footer></el-form></section></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import type{FormInstance,FormRules}from'element-plus';import{ElMessage}from'element-plus';import{ArrowLeft,Check}from'@element-plus/icons-vue';import{useRoute,useRouter}from'vue-router';import RoleBasicForm from'./components/RoleBasicForm.vue';import PermissionMatrix from'./components/PermissionMatrix.vue';import{permissionCatalog}from'../permissionCatalog';import{getRole,saveRole}from'../rolePrototypeStore';import type{RolePayload}from'../types';const route=useRoute();const router=useRouter();const formRef=ref<FormInstance>();const submitting=ref(false);const id=computed(()=>Number(route.params.id)||undefined);const isEdit=computed(()=>Boolean(id.value));const form=reactive<RolePayload>({name:'',status:1,permissions:[]});const rules:FormRules<RolePayload>={name:[{required:true,message:'请输入角色名称',trigger:'blur'},{min:2,max:40,message:'角色名称为 2–40 个字符',trigger:'blur'}],permissions:[{type:'array',required:true,min:1,message:'请至少选择一项权限',trigger:'change'}]};onMounted(()=>{if(!id.value)return;const role=getRole(id.value);if(!role){ElMessage.error('未找到该角色');back();return}Object.assign(form,{name:role.name,status:role.status,permissions:[...role.permissions]})});function back(){history.length>1?router.go(-1):void router.push({name:'RoleManagement'})}async function submit(){const valid=await formRef.value?.validate().catch(()=>false);if(!valid)return;submitting.value=true;try{saveRole({name:form.name.trim(),status:form.status,permissions:[...form.permissions]},id.value);ElMessage.success(isEdit.value?'角色已更新':'角色已新增');await router.replace({name:'RoleManagement'})}finally{submitting.value=false}}</script>
<style scoped lang="scss">.role-form-page{display:grid;gap:16px}.role-form-page__toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px}.role-form-page__toolbar>div{display:flex;align-items:center;gap:12px}.role-form-page__toolbar h1{margin:0;color:#10243d;font-size:24px}.role-form-page .el-form{display:grid;gap:16px}.role-form-page__footer{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border:1px solid #dfe8ef;border-radius:14px;background:#fff;box-shadow:0 8px 24px rgb(25 62 96 / 6%);color:#60758b;font-size:13px}.role-form-page__footer b{color:#079c92}@include mobile{.role-form-page__toolbar{align-items:flex-start;flex-direction:column}.role-form-page__toolbar>div:last-child{width:100%}.role-form-page__toolbar>div:last-child .el-button{flex:1}.role-form-page__footer{align-items:stretch;flex-direction:column;gap:12px}.role-form-page__footer .el-button{width:100%}}</style>
